(() => {
const C=window.CURTAIN_CONTENT;
const material={
stone:[['保存的究竟是什么','蕴法石能够保存完整的咒语，使用时将其释放。它与造物中保存的初步塑形魔力不同：造物通常维持某种性质或效果，蕴法石则对应已经封入的具体咒语。','释放后的蕴法石不能再次填充。一次性使用的限制，使矿物的开采、填充和运输成为一条持续运作的生产链。'],['石材的体积','石材体积影响可以保存的咒语数量与复杂程度，并不直接决定咒语的等级。简单咒语可能只占用石材的一部分；更复杂的结构则需要更大的容量。','一块石头在填满之前可以吸收不同的咒语，但混入不同咒语后，它们可能互相干扰或抵消。使用层面的可靠性，要求填充者认真控制其中保存的内容。'],['工业与废石','工业设备可以使用存有大量同一种咒语的大块蕴法石。机器连续调用其中的咒语，以多次释放维持运行；大块石材解决的是续航，而不是自动提高单次释放的威力。','使用过的石头仍可能进入建材、研磨材料或炼金原料市场。例如，曾经承载防御咒语的废石可能具有适合建筑用途的结构残余。废石因此并非完全没有价值。'],['尚未说清的发现史','较早时期，蕴法石曾因能够吸收咒语而被作为防御材料使用。它能够再次释放所吸收的咒语这一性质何时、由谁发现，现有材料仍未确定。'] ],
gates:[['界门的建造与维护','界门是大型圣律造物，由空间魔法体系的顶尖巫师共同建造，并由魔法联合部维护和监管。它并不是每个城镇都有的公共设施，主要分布于首都、大城市、战略要地与联合部控制的地区。','因此，地图上两点之间即使存在界门联系，旅客仍需要先抵达门所在的城市，并承担使用费用。网络的分布决定了哪些地方能够便利地接入跨大陆交通。'],['费用与旅行机会','界门的费用对普通居民而言相当高昂。高级巫师、政府官员、商人和军方更容易承担这项开支；不少普通居民可能终生没有离开出生的大陆。','对频繁旅行的使用者来说，五大陆可以通过一系列节点相连；对无法负担界门费用的人来说，海洋、陆路和旅行时间仍然构成真实的距离。研究交通时，技术能力和使用机会需要分开考察。']],
alchemy:[['共同源流与分离的传统','早期炼金术同时出现在巫师和质人族的传统中，两者具有共同源流，确切起源已经难以考证。早期实践涉及魔药、造物，也包括后来被视为高风险的生命改造技术。','巫师在早期聚居程度有限，炼金知识多以分散方式传承。大迁徙以后，随着聚居与知识整理发展，巫师的相关实践逐渐分化为魔药学和造物术。'],['不同的分类','巫师学者通过分类、记录和教育建立较为系统的学科，人体炼成和血祭造物等高风险实践则受到限制。部分古老家族和其他炼金传统仍保存相关技术，但在现行制度下受到约束。','质人族的炼金传统没有沿完全相同的路径分化。不同群体对自身技术的分类与风险理解存在差异，不能简单地把巫师学界的术语套到所有实践之上。'],['语言造成的距离','长期分离和早期关系紧张，使不同群体使用的工具、步骤与术语逐渐产生差异。两种方法即使最终得到相近的魔药，也不一定能够直接用同一套知识解释。','这种交流困难不是某个简单误会。要比较两种传统，研究者需要理解各自完整的操作过程，而不只是比较最终成品。']],
wands:[['为什么长杖适合古代施法','长杖提供较长的力量导出路径，有助于自然力量的共鸣和远距离引导。古代大型施法通常需要较长的吟唱、引导，有时还需要多位巫师共同参与。','这种方式能在适当条件下调动大量自然力量，但准备时间、空间和施法者的身体承受能力都会限制它的用途。回路受损或施法能力衰退是不可忽视的代价。'],['城市与短杖','随着城市、楼宇和密集街巷的发展，施法的空间与时间条件发生变化。短杖便于快速导出力量，现代咒语也更注重灵活性、精确度和较低的持续负荷。','这并不意味着新工具在所有场合都优于旧工具。长距离引导和近距离快速施法面对不同问题，研究工具史需要同时考察它们各自的使用环境。'],['工具如何参与施法','施法媒介不只是将魔力送出体外。它还辅助稳定，并在导出时参与咒语的最终定型。长期使用使巫师熟悉工具与自身回路的配合，这种熟悉本身也是训练的一部分。']],
continents:[['土地、人口与未开发区域','五大陆总陆地面积约五千万平方公里，人口约九亿。人口分布并不均匀；城市、农田与交通节点之间，还存在危险森林、荒原、魔法禁区及各类居民的栖息地。','地理研究不能只把这些区域看作等待利用的空白。许多地方已有长期生活于此的群体，也有尚未被外来调查者充分记录的自然环境。'],['资源与分工','埃斯佩兰萨的蕴法石矿脉丰富，是重要的原料输出地；卡莫瑞亚则因高级巫师相对集中，在咒语填充方面拥有显著优势。原料产地和掌握加工能力的地方并不总是相同。','艾森洛德的精密操作和结界传统支撑造物制造；茨威尔格诺出产蕴法石和神奇生物皮毛；昂尚特维斯的森林则提供草药与魔药原料。'],['研究地方文化','大陆名称提供地理尺度，却不能覆盖其中所有居民的经验。来自不同群体、地区与职业的人，对同一片土地可能有不同认识；地方传统的概括需要为这些差异留出空间。']],
traditions:[['基础实践与专门研究','意念移物、简单变形和基础元素操纵流传较广。随着学习深入，施法者可能进入更专门的魔法体系，如结界、精密操作、预言、神圣、海洋和梦境等。','基础与高级的区分有助于组织教学，但不能把它理解成不同实践互不相关。基础训练提供的控制能力，往往仍然影响后续研究。'],['权柄研究中的两种关系','不同魔法体系有时可能通向同一个权柄；一种体系也可能包含通往不同权柄的路径。这意味着，研究传统与其最深层的自然规律之间，并不是简单的一一对应。','权柄在同一时间具有独一性。掌握者去世后，权柄回归自然；这并不意味着研究者只要沿既有路线学习，就能稳定地达到相同结果。']],
ministry:[['联合部与跨地区事务','在贵族长期影响地方政治之后，跨地区贸易、争端和魔法活动的管理逐渐超出单一地方机构能够处理的范围。部分贵族家族的领导者共同建立联合部，试图建立更稳定的协调与执行机制。','总部位于卡莫瑞亚的普诺伊瓦。随着机构发展，官僚体系和执行力量逐渐形成，公共权威开始具有超越单个家族的地位。'],['制度与日常生活','联合部维护和监管界门网络，也参与造物管理及通用货币发行。对普通居民而言，政治制度不仅体现在重大决策中，也体现在旅行费用、商品流通和物品登记等日常事务中。','较危险的圣律造物需要登记，神权造物也受到监管。机构权威的形成改变了权力分配，但过去积累的家族知识和资源仍可能继续影响公共生活。']]
};
for(const [id,chapters] of Object.entries(material)){const a=C.articles.find(x=>x.id===id);if(!a)continue;for(const [heading,...paragraphs] of chapters)a.chapters.push({heading,paragraphs});a.paragraphs=a.chapters.flatMap(c=>c.paragraphs)}
const add=(id,section,title,subtitle,lead,source,chapters)=>C.articles.push({id,section,title,subtitle,lead,source,eyebrow:'社会与文明 / 研究文章',chapters:chapters.map(([heading,...paragraphs])=>({heading,paragraphs})),paragraphs:chapters.flatMap(([, ...p])=>p)});
add('currency-study','geography','从索比恩到加令','通用货币与跨大陆交易','货币让价格得以比较，也记录了一套政治秩序如何获得人们的承认。',['货币'],[
['信用从何而来','帷幕世界的通用货币由魔法联合部发行。它的信用建立在联合部的政治与魔法权威之上，而非直接以黄金或土地作为锚定。','这种制度让联合部拥有重要的货币管理能力，也使通用货币的流通与公共权力之间存在密切关系。'],
['两套单位','索比恩用于日常交易。更大额的交易使用加令体系：一铜加令等于一百索比恩，十二铜加令等于一银加令，十二银加令等于一金加令。','混合进制反映了不同历史阶段的叠加。索比恩作为较古老的民间散钱，与后来规范化的加令共同存在；一金加令相当于一万四千四百索比恩。'],
['通用与地方','卡莫瑞亚使用通用货币体系，其他大陆也有本土货币。通用货币在跨地区交易中具有重要地位，但这不意味着地方经济的所有结算方式都已经统一。','帷幕与人类世界之间不存在公开的人民币兑换体系。跨界交易更多依靠材料、魔药、造物、技术及信息等资源交换。']]);
add('food-and-work','geography','粮食、机器与日常劳动','魔法社会的生产与限制','有魔法的世界仍然需要耕种、运输、机器维护和支付生活费用。',['生产力与农业','蕴法石'],[
['工业的动力','帷幕世界的工业面貌可以与第二次工业革命时期作比较，但许多机器依靠魔力驱动。齿轮、织机和工坊并没有消除手工劳动，两种方式在不同生产场景中并存。','工业所需的蕴法石必须预先填充咒语。机器的运转因此与矿物开采、施法者的劳动以及供给网络相联系。'],
['魔法不能凭空消除饥饿','低等级催熟魔法产生的作物在产量、口感和营养方面都存在明显问题，也难以作为可靠的副产品原料。畜牧业同样面临类似限制。','高级催熟魔法可以取得更好的效果，但成本往往高到农场主难以负担。魔法能够辅助生产，却不能自动让粮食变得无限而廉价。'],
['普通家庭的生活','当粮食依然需要生产与交换，普通居民仍需要为食物支付货币。观察农业和市场，可以帮助我们理解宏大的魔法体系如何与最基本的生活条件相连。']]);
add('artefacts-study','magic','造物：被保存的魔力','可重复使用的器物与管理','一件造物保存的不是一次完整咒语，而是能够反复发挥的魔力性质。',['造物体系'],[
['什么称得上造物','造物是可重复使用、蕴含已塑形魔力的无生命器物。它保存的是特定的性质、效果或塑形方式；与之相比，蕴法石保存的是可供释放的完整咒语。','造物并不一定要求使用者具有高深的施法技巧，无魔力者也可能使用。使用者与造物的契合程度仍会影响它能否发挥最大效能。'],
['恢复与补充','造物中的魔力可以缓慢地从自然环境中恢复。人为补充则困难得多：输入的魔力需要适当塑形，还要与造物内部的魔力流相契合。','造物师可以请其他施法者参与铸造和灌注，因此造物品质不必等同于制作者本人的战斗能力。创造、灌注和后续恢复是需要分别理解的过程。'],
['分级与登记','大部分低等级造物可以在市场流通。较危险的律痕级造物以及更高等级的圣律造物受到严格监管，持有和转让需要登记；神权造物也受到联合部监管。','监管不等于所有物品都由联合部直接拥有。不同国家可能保留本国的神权造物，并按照制度登记。']]);
})();
